fn sv(i: i32) -> i32 {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    tab[i & 31]
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x02060a);
    let base: i32 = h - 40;
    let mut x: i32 = 0;
    while x < w {
        let v: i32 = sv(x / 16 + t / 8) + sv(x / 7 + t / 3) / 2;
        let ah: i32 = 40 + (v + 190) * (h - 120) / 380;
        host::display::fill_rect(x, base - ah, 4, ah, 0x0a4060);
        host::display::fill_rect(x, base - ah, 4, 2, 0x40c0ff);
        x = x + 4;
    }
    host::display::draw_line(0, base, w - 1, base, 0x808080);
    host::display::draw_string(8, 8, "THROUGHPUT", 0x808080, 1);
    host::display::present();
}
